export const fresh=()=>({version:1,lamp:false,angle:0,light:false,chest:false,path:[],door:false,hints:0,selected:null,names:['台灯','镜子','书'],flavor:null,source:'HANDCRAFTED'});
export function act(s,a){const n=structuredClone(s);let result='';if(a.type==='lamp')n.lamp=!n.lamp;if(a.type==='rotate')n.angle=((n.angle+a.delta)%180+180)%180;if(n.lamp&&n.angle===90)n.light=true;if(a.type==='unlock'){if(!n.light)result='needLight';else if(String(a.code).trim()==='417'){n.chest=true;result='unlocked'}else result='wrongCode'}if(a.type==='direction'){if(!n.chest)result='needLeaf';else{const expected=['N','E','W'];if(a.value===expected[n.path.length]){n.path.push(a.value);result='step';if(n.path.length===3){n.door=true;result='opened'}}else{n.path=[];result='wrongPath'}}}return {state:n,result};}
export function restore(raw){try{const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.names)||s.names.length!==3||s.names.some(x=>typeof x!=='string'||x.length>24))return fresh();const base=fresh();for(const k of ['lamp','light','chest','door'])if(typeof s[k]!=='boolean')return fresh();if(![0,45,90,135].includes(s.angle))return fresh();if(!Array.isArray(s.path)||s.path.some((x,i)=>x!==['N','E','W'][i]))return fresh();return {...base,...s,selected:null};}catch{return fresh()}}
export function validFlavor(x){return x&&['intro','lamp','mirror','book','ending'].every(k=>typeof x[k]==='string'&&x[k].length>0&&x[k].length<=550)}
